// QRCode.js simple implementation for MVP
var QRCode = (function() {
    function QRCode(element, options) {
        this.element = element;
        this.options = options || {};
        this.text = this.options.text || '';
        this.width = this.options.width || 256;
        this.height = this.options.height || 256;
        
        if (this.text) {
            this.makeCode(this.text);
        }
    }
    
    QRCode.prototype.makeCode = function(text) {
        this.text = text;
        this.element.innerHTML = '';
        
        // Crear canvas para el QR
        var canvas = document.createElement('canvas');
        canvas.width = this.width;
        canvas.height = this.height;
        
        var ctx = canvas.getContext('2d');
        
        // Fondo blanco
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, this.width, this.height);
        
        // Crear patrón simple de QR (para demo)
        var size = this.width / 25;
        var qrData = this.generateQRPattern(text);
        
        ctx.fillStyle = '#000000';
        for (var i = 0; i < 25; i++) {
            for (var j = 0; j < 25; j++) {
                if (qrData[i][j]) {
                    ctx.fillRect(i * size, j * size, size, size);
                }
            }
        }
        
        this.element.appendChild(canvas);
    };
    
    QRCode.prototype.generateQRPattern = function(text) {
        var pattern = [];
        var hash = this.simpleHash(text);
        
        // Crear patrón 25x25
        for (var i = 0; i < 25; i++) {
            pattern[i] = [];
            for (var j = 0; j < 25; j++) {
                // Esquinas de posicionamiento
                if ((i < 7 && j < 7) || (i < 7 && j > 17) || (i > 17 && j < 7)) {
                    pattern[i][j] = (i === 0 || i === 6 || j === 0 || j === 6 || 
                                   (i >= 2 && i <= 4 && j >= 2 && j <= 4));
                } else {
                    // Patrón basado en hash del texto
                    pattern[i][j] = ((hash + i * 7 + j * 13) % 3) === 0;
                }
            }
        }
        
        return pattern;
    };
    
    QRCode.prototype.simpleHash = function(str) {
        var hash = 0;
        for (var i = 0; i < str.length; i++) {
            var char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash; // Convertir a 32bit
        }
        return Math.abs(hash);
    };
    
    QRCode.prototype.clear = function() {
        this.element.innerHTML = '';
    };
    
    return QRCode;
})();

// Exportar para uso global
if (typeof module !== 'undefined' && module.exports) {
    module.exports = QRCode;
}
